mapper.select:
SELECT so.id AS order_id, so.order_no, c.customer_name, so.total_amount, COALESCE(inv.invoiced, 0) AS invoiced, so.total_amount - COALESCE(inv.invoiced, 0) AS uninvoiced, COALESCE(rec.received, 0) AS received, so.total_amount - COALESCE(rec.received, 0) AS unreceived FROM sales_order so LEFT JOIN customer c ON so.customer_id = c.id LEFT JOIN (SELECT order_id, SUM(total_amount) AS invoiced FROM invoice WHERE status=1 GROUP BY order_id) inv ON so.id = inv.order_id LEFT JOIN (SELECT order_id, SUM(amount) AS received FROM receipt GROUP BY order_id) rec ON so.id = rec.order_id
AND so.company_id = #{params.companyId}
ORDER BY so.id DESC
